import 'package:flutter/material.dart';import '../data/app_store.dart';import '../data/timer_repository.dart';import '../models/models.dart';import '../models/operator_timer.dart';import '../widgets/common.dart';
class HandoverScreen extends StatefulWidget{final AppStore store;const HandoverScreen({super.key,required this.store});@override State<HandoverScreen> createState()=>_S();}
class _S extends State<HandoverScreen>{List<OperatorTimer> timers=[];@override void initState(){super.initState();TimerRepository().load().then((x){if(mounted)setState(()=>timers=x);});}
@override Widget build(BuildContext c){final open=widget.store.tasks.where((x)=>x.state!=ActionState.completed),maint=widget.store.equipment.where((x)=>x.state==EquipmentState.maintenance||x.state==EquipmentState.outOfService||x.state==EquipmentState.taggedOut),activeTimers=timers.where((x)=>!x.acknowledged);return Scaffold(appBar:AppBar(title:const Text('Shift handover')),body:ListView(children:[const SectionLabel('Open actions'),...open.map((e)=>ListTile(title:Text(e.title),subtitle:Text(e.equipmentTag??'General'))),const SectionLabel('Equipment unavailable / maintenance'),...maint.map((e)=>ListTile(title:Text(e.tag),subtitle:Text('${e.name} · ${e.state.name}'))),const SectionLabel('Watch items'),...widget.store.watch.where((e)=>e.active).map((e)=>ListTile(title:Text(e.equipmentTag??e.title),subtitle:Text('${e.title} · ${e.detail}'))),const SectionLabel('Timers / reminders'),if(activeTimers.isEmpty)const ListTile(title:Text('No unacknowledged timers')),...activeTimers.map((e)=>ListTile(title:Text(e.title),subtitle:Text('${e.equipmentTag??'General'} · due ${hhmm(e.dueAt)}'))),const SectionLabel('Recent shift activity'),...widget.store.logs.take(10).map((e)=>ListTile(title:Text(e.text),subtitle:Text(hhmm(e.createdAt)))),const SizedBox(height:30)]));}}
